      "alt": "The word Slop scraped through a mound of thick peach, orange and lilac paint.",
      "prompt": "Use case: stylized-concept. Generate one independent square artwork, 1024 by 1024, filling the image. A thick impasto oil painting seen straight on: an extravagant mound of peach, hot orange, dirty lilac and butter-yellow paint pushed across a deep brown ground. The paint has weight, dragged ridges, glossy wet pockets and drying skins. Make the exact word \"Slop\" the main form, with an uppercase S and lowercase lop. Its letters are broad channels scraped through the mound with a blunt palette knife, exposing the dark ground beneath. A lumpy ribbon of paint falls into the open bowl of the p. The composition should feel physically generous and slightly nauseating, with uneven letter widths and an off-center mass. Light rakes across the surface from the upper left. Show only the painting itself, edge to edge.",
