      "prompt": "Use case: stylized-concept. Make a square conceptual drawing on a single battered sheet of cream paper, reproduced straight on and filling the image. The sheet has been densely worked with graphite, black correction ink and broad redaction bars. The exact words \"Authorship unavailable\" survive as untouched paper within the darkest central band, formed by careful erasure and irregular masked edges. Give the composition the severe balance of an official record that has been handled too often: a sparse upper field, a heavy black middle, and delicate pressure marks below. Small torn fibers, finger grease, pinholes and a faint abandoned pencil grid reward close looking. The wording is the drawing's exposed gap. Keep it readable across two uneven lines, surrounded by marks that almost become writing but remain abstract. The ink should absorb light.",
