      "alt": "Sagging pink and pale green neon tubes spell Feeling generated against a stained dark panel.",
      "prompt": "Use case: stylized-concept. Create a square photograph of a neon sculpture filling most of a dark, shallow space. Bent glass tubes spell exactly \"Feeling generated\" in two connected, slightly drooping lines. The first word glows bruised pink and the second an icy pale green; each stroke has real thickness, dark electrode caps and small uneven gaps. The tubes sag into a loose downward arc, as if the sentence has become tired under its own weight. Fine support wires, transformer leads and one exposed mounting screw remain visible. Their shadows cross a stained brown-black backing panel. Use a close, frontal camera and restrained exposure so the glass remains distinct inside its glow. Pools of colored light stain the panel, and one long tube has a dim patch without losing the letter. The artwork is the luminous sentence and its physical supports.",
