      "alt": "Crisp colored planes descend like steps, with A step below average cut into the lowest plane.",
      "prompt": "Use case: stylized-concept. Create a square hard-edge abstract painting with a precise but faintly absurd sense of measurement. Five broad colored planes form a staircase descending from the top left toward the lower right. Use chalky coral, ochre, deep navy, pale mint and a large cream field, with very crisp taped edges and slight paint buildup where colors meet. At the lowest step, carve the exact phrase \"A step below average\" into the painted surface in small, clean lowercase and uppercase lettering matching that capitalization. The cut letters expose a rough brown underlayer, and the baseline sits visibly lower than the stair's edge. Let the upper half breathe while the lowest plane crowds the bottom edge. This should read first as a strong geometric painting, then as a quiet complaint embedded in its construction. Fill the frame with the painted surface.",
